/**
 * A task node. Tasks can nest any number of sub-tasks.
 * A task with no sub-tasks is a "leaf" and is checked off directly;
 * a parent's progress is derived from its leaves.
 */
export type Task = {
  id: string;
  title: string;
  description?: string;
  done: boolean;
  subtasks: Task[];
};

/**
 * A project — the top level of the trellis (e.g. "FPS").
 */
export type Project = {
  id: string;
  name: string;
  description?: string;
  color?: string;
  tasks: Task[];
  createdAt?: string;
  updatedAt?: string;
};

/**
 * Fields accepted when creating or updating a project.
 */
export type ProjectInput = Omit<Project, 'id' | 'createdAt' | 'updatedAt'>;
